21	namespace optiling {
22	class TilingDefImpl;
23	struct CharPtrCmp {
24	  bool operator()(const char *strLeft, const char *strRight) const {
25	    return strcmp(strLeft, strRight) < 0;
26	  }
27	};
28	
29	class StructSizeInfoBase {
30	 public:
31	  static StructSizeInfoBase &GetInstance() {
32	    static StructSizeInfoBase instance;
33	    return instance;
34	  }
35	  void SetStructSize(const char *structType, const size_t structSize) {
36	    if (structSizeInfo.find(structType) != structSizeInfo.end()) {
37	      return;
38	    }
39	    structSizeInfo[structType] = structSize;
40	  }
41	  size_t GetStructSize(const char *structType) {
42	    return structSizeInfo.at(structType);
43	  }
44	
45	 private:
46	  StructSizeInfoBase(){};
47	  ~StructSizeInfoBase(){};
48	  StructSizeInfoBase(const StructSizeInfoBase &);
49	  StructSizeInfoBase &operator=(const StructSizeInfoBase &);
50	  std::map<const char *, size_t, CharPtrCmp> structSizeInfo;
51	};
52	
53	class FieldInfo {
54	 public:
55	  FieldInfo(const char *dtype, const char *name) : dtype_(dtype), name_(name), classType_("0") {}
56	  FieldInfo(const char *dtype, const char *name, size_t arrSize)
57	      : dtype_(dtype), name_(name), arrSize_(arrSize), classType_("1") {}
58	  FieldInfo(const char *dtype, const char *name, const char *structType, size_t structSize)
59	      : dtype_(dtype), name_(name), structType_(structType), structSize_(structSize), classType_("2") {}
60	
61	 public:
62	  const char *dtype_;
63	  const char *name_;
64	  size_t arrSize_;
65	  const char *structType_;
66	  size_t structSize_;
67	  const char *classType_;
68	};
69	
70	class TilingDef {
71	 public:
72	  ~TilingDef() {
73	    if (!inited_data_ptr && data_ptr_ != nullptr) {
74	      delete[] data_ptr_;
75	    }
76	    data_ptr_ = nullptr;
77	    class_name_ = nullptr;
78	  }
79	  void SaveToBuffer(void *pdata, size_t capacity);
80	  std::vector<FieldInfo> GetFieldInfo() const;
81	  const char *GetTilingClassName() const;
82	  size_t GetDataSize() const;
83	  void SetDataPtr(void *dataPtr);
84	  void CheckAlignAndGenPlaceHolder(const char *name, size_t typeSize);
85	
86	 protected:
87	  void InitData();
88	  void GeLogError(const std::string &str) const;
89	  // dtype, name
90	  std::vector<FieldInfo> field_info_;
91	  uint8_t *data_ptr_ = nullptr;
92	  size_t data_size_ = 0;
93	  const char *class_name_;
94	  std::vector<std::pair<void *, size_t>> saveBufferPtr;
95	  size_t struct_size_ = 0;
96	  bool inited_data_ptr = false;
97	  uint32_t feature_bit_flag = 0;
98	  uint8_t reserved_buf[128] = {0};
99	  friend class TilingDefImpl;
100	};
101	
102	using TilingDataConstructor = std::shared_ptr<TilingDef> (*)();
103	
