135	/*
136	example:
137	// supported data_type: int8_t/uint8_t/int16_t/uint16_t/int32_t/uint32_t/int64_t/uint64_t
138	BEGIN_TILING_DATA_DEF(MaxPoolTilingData)
139	    // format: TILING_DATA_FIELD_DEF(data_type, field_name);
140	    TILING_DATA_FIELD_DEF(int32_t, dim_0);
141	    TILING_DATA_FIELD_DEF(uint8_t, var_1);
142	    TILING_DATA_FIELD_DEF(int64_t, factor_1);
143	END_TILING_DATA_DEF
144	REGISTER_TILING_DATA_CLASS(MaxPool, MaxPoolTilingData)
145	*/
146	#define BEGIN_TILING_DATA_DEF(class_name)                                                                           \
147	  class class_name : public TilingDef {                                                                             \
148	   public:                                                                                                          \
149	    size_t FieldHandler(const char *dtype, const char *name, size_t typeSize, const char *namePh) {                 \
150	      CheckAlignAndGenPlaceHolder(namePh, typeSize);                                                                \
151	      field_info_.emplace_back(FieldInfo(dtype, name));                                                             \
152	      size_t ret_val = data_size_;                                                                                  \
153	      data_size_ += typeSize;                                                                                       \
154	      return ret_val;                                                                                               \
155	    }                                                                                                               \
156	    size_t FieldHandler(const char *dtype, const char *name, size_t typeSize, size_t arrSize, const char *namePh) { \
157	      CheckAlignAndGenPlaceHolder(namePh, typeSize);                                                                \
158	      field_info_.emplace_back(FieldInfo(dtype, name, arrSize));                                                    \
159	      size_t ret_val = data_size_;                                                                                  \
160	      data_size_ += typeSize * arrSize;                                                                             \
161	      return ret_val;                                                                                               \
162	    }                                                                                                               \
163	    size_t FieldHandler(const char *dtype, const char *name, const char *structType, size_t structSize, void *ptr,  \
164	                        const char *namePh) {                                                                       \
165	      CheckAlignAndGenPlaceHolder(namePh, 8);                                                                       \
166	      field_info_.emplace_back(FieldInfo(dtype, name, structType, structSize));                                     \
167	      size_t ret_val = data_size_;                                                                                  \
168	      data_size_ += structSize;                                                                                     \
169	      saveBufferPtr.emplace_back(std::make_pair(ptr, ret_val));                                                     \
170	      struct_size_ += structSize;                                                                                   \
171	      return ret_val;                                                                                               \
172	    }                                                                                                               \
173	                                                                                                                    \
174	   public:                                                                                                          \
175	    class_name() {                                                                                                  \
176	      class_name_ = #class_name;                                                                                    \
177	      CheckAlignAndGenPlaceHolder(#class_name "PH", 8);                                                             \
178	      StructSizeInfoBase::GetInstance().SetStructSize(#class_name, data_size_);                                     \
179	      InitData();                                                                                                   \
180	    }                                                                                                               \
181	    explicit class_name(void *ptr) {                                                                                \
182	      class_name_ = #class_name;                                                                                    \
183	      CheckAlignAndGenPlaceHolder(#class_name "PH", 8);                                                             \
184	      StructSizeInfoBase::GetInstance().SetStructSize(#class_name, data_size_);                                     \
185	      if (ptr == nullptr) {                                                                                         \
186	        return;                                                                                                     \
187	      }                                                                                                             \
188	      SetDataPtr(ptr);                                                                                              \
189	    }
190	
191	#define TILING_DATA_FIELD_DEF(data_type, field_name)                                                        \
192	 public:                                                                                                    \
193	  void set_##field_name(data_type field_name) {                                                             \
194	    field_name##_ = field_name;                                                                             \
195	    *((data_type *)(data_ptr_ + field_name##_offset_)) = field_name;                                        \
196	  }                                                                                                         \
197	  data_type get_##field_name() {                                                                            \
198	    return field_name##_;                                                                                   \
199	  }                                                                                                         \
200	                                                                                                            \
201	 private:                                                                                                   \
202	  data_type field_name##_ = 0;                                                                              \
203	  size_t field_name##_offset_ = FieldHandler(#data_type, #field_name, sizeof(data_type), #field_name "PH"); \
204	  uint8_t field_name##_reserve_buf_[16] = {0};
205	
206	#define TILING_DATA_FIELD_DEF_ARR(arr_type, arr_size, field_name)                                                    \
207	 public:                                                                                                             \
208	  void set_##field_name(arr_type *field_name) {                                                                      \
209	    auto offset = field_name##_offset_;                                                                              \
210	    if (data_ptr_ + offset == (uint8_t *)field_name) {                                                               \
211	      return;                                                                                                        \
212	    }                                                                                                                \
213	    const auto err_t = memcpy_s(data_ptr_ + offset, data_size_ - offset, field_name, (arr_size) * sizeof(arr_type)); \
214	    if (err_t != EOK) {                                                                                              \
215	      GeLogError("tilingdata_base.h TILING_DATA_FIELD_DEF_ARR memcpy is failed !");                                  \
216	    }                                                                                                                \
217	  }                                                                                                                  \
218	  arr_type *get_##field_name() {                                                                                     \
219	    return (arr_type *)(data_ptr_ + field_name##_offset_);                                                           \
220	  }                                                                                                                  \
221	                                                                                                                     \
222	 private:                                                                                                            \
223	  arr_type *field_name##_ = nullptr;                                                                                 \
224	  size_t field_name##_offset_ = FieldHandler(#arr_type, #field_name, sizeof(arr_type), arr_size, #field_name "PH");  \
225	  uint8_t field_name##_reserve_buf_[16] = {0};
226	
227	#define TILING_DATA_FIELD_DEF_STRUCT(struct_type, field_name)                                                          \
228	 public:                                                                                                               \
229	  struct_type field_name{nullptr};                                                                                     \
230	                                                                                                                       \
231	 private:                                                                                                              \
232	  size_t field_name##_offset_ =                                                                                        \
233	      FieldHandler("struct", #field_name, #struct_type, StructSizeInfoBase::GetInstance().GetStructSize(#struct_type), \
234	                   (void *)&field_name, #field_name "PH");                                                             \
235	  uint8_t field_name##_reserve_buf_[16] = {0};
236	
237	#define END_TILING_DATA_DEF \
238	  }                         \
239	  ;
240	
241	#define REGISTER_TILING_DATA_CLASS(op_type, class_name)                          \
242	  namespace {                                                                    \
243	  class op_type##class_name##Helper {                                            \
244	   public:                                                                       \
245	    op_type##class_name##Helper() {                                              \
246	      CTilingDataClassFactory::GetInstance().RegisterTilingData(                 \
247	          #op_type, op_type##class_name##Helper::CreateTilingDataInstance);      \
248	    }                                                                            \
249	    static std::shared_ptr<TilingDef> CreateTilingDataInstance() {               \
250	      return std::make_shared<class_name>();                                     \
251	    }                                                                            \
252	  };                                                                             \
253	  static class_name g_##op_type##class_name##init;                               \
254	  static op_type##class_name##Helper g_tilingdata_##op_type##class_name##helper; \
255	  }
256	#endif  // __INC_REGISTER_ASCENDC_TILINGDATA_BASE_HEADER__
257

