418	template <AttrDataType SRC, AttrDataType DST>
419	class AttrTable {
420	 public:
421	  explicit AttrTable(const AppendAttrFunc default_val) {
422	    for (size_t i = 0UL; i < static_cast<size_t>(SRC); ++i) {
423	      for (size_t j = 0UL; j < static_cast<size_t>(DST); ++j) {
424	        elements[i][j] = default_val;
425	      }
426	    }
427	  }
428	
429	  AppendAttrFunc Find(AttrDataType src, AttrDataType dst) const {
430	    if (src >= SRC || dst >= DST) {
431	      return nullptr;
432	    }
433	    return elements[static_cast<size_t>(src)][static_cast<size_t>(dst)];
434	  }
435	
436	  AttrTable &Add(AttrDataType src, AttrDataType dst, AppendAttrFunc func) {
437	    elements[static_cast<size_t>(src)][static_cast<size_t>(dst)] = func;
438	    return *this;
439	  }
440	
441	 private:
442	  std::array<std::array<AppendAttrFunc, static_cast<size_t>(DST)>, static_cast<size_t>(SRC)> elements{};
443	};
