596	// src type and dst type are enum data
597	ge::graphStatus TilingData::AppendConvertedAttrVal(const RuntimeAttrs *attrs, const size_t attr_index,
598	                                                   const AttrDataType src_type, const AttrDataType dst_type) {
599	  GE_CHECK_NOTNULL(attrs);
600	  if (attr_index >= attrs->GetAttrNum()) {
601	    GELOGE(ge::GRAPH_FAILED, "Attr index is invalid, out of range %zu.", attrs->GetAttrNum());
602	    return ge::GRAPH_FAILED;
603	  }
604	  auto func = kAttrTable.Find(src_type, dst_type);
605	  if (func == nullptr) {
606	    GELOGE(ge::GRAPH_FAILED, "Get attr index[%zu] and transform from [%d] to [%d] is not supported.", attr_index,
607	           static_cast<int32_t>(src_type), static_cast<int32_t>(dst_type));
608	    return ge::GRAPH_FAILED;
609	  }
610	  GELOGD("Get attr index[%zu] success and begin to transform from [%d] to [%d].", attr_index,
611	         static_cast<int32_t>(src_type), static_cast<int32_t>(dst_type));
612	  return func(this, attrs, attr_index);
613	}
