27	gert::ContextHolder<gert::TilingContext> BuildTestContext() {
28	  uint8_t tmp_compile_info[] = {1, 2, 3, 4, 5, 6, 7};
29	  uint8_t tmp_platform_info[] = {1, 2, 3, 4, 5, 6, 7};
30	  OpTilingContextBuilder ctx_builder;
31	  auto holder = ctx_builder.IONum(1, 1)
32	                    .OpName("tmp")
33	                    .OpType("DIY")
34	                    .CompileInfo(tmp_compile_info)
35	                    .PlatformInfo(tmp_platform_info)
36	                    .AppendAttr(ge::AscendString("Hello!"))
37	                    .AppendAttr(float(10.101))
38	                    .AppendAttr(std::vector<float>({1.2, 2.3, 3.4}))
39	                    .AppendAttr(std::vector<std::vector<int64_t>>({{1, 2, 3}, {4, 5, 6}}))
40	                    .AppendAttr(int64_t(0x7fUL))
41	                    .AppendAttr(std::vector<int64_t>({1, 2, 3}))
42	                    .AppendAttr(std::vector<std::vector<int64_t>>({{1, 2, 3}, {4, 5, 6}}))
43	                    .AppendAttr(bool(true))
44	                    .AppendAttr(std::vector<bool>({true, false, true}))
45	                    .Build();
46	  return holder;
47	}
