78	  ASSERT_NE(ptr, nullptr);
79	  ASSERT_EQ(tiling_data->GetDataSize(), 80 + sizeof(int64_t));
80	  *reinterpret_cast<int64_t *>(ptr) = test_data;
81	  gold.push_back(test_data);
82	  EXPECT_EQ(memcmp(tiling_data->GetData(), gold.data(), tiling_data->GetDataSize()), 0);
83	}
