20	bool CheckPathIsHeader(std::string file) {
21	  const std::string suffix = ".h";
22	  if (suffix.size() > file.size()) {
23	    return false;
24	  }
25	  return file.substr(file.size() - suffix.size()) == suffix;
26	}
