52	void TilingDefImpl::GeLogError(const std::string &str) {
53	#ifndef ASCENDC_DEVICE_REG_STATIC
54	  GELOGE(ge::GRAPH_FAILED, "%s", str.c_str());
55	#endif
56	  (void)str;  // to avoid unused parameter warning
57	}
58	
59	void TilingDefImpl::SetDataPtr(TilingDef &tiling, void *dataPtr) {
60	  if (!tiling.inited_data_ptr && tiling.data_ptr_ != nullptr) {
61	    delete[] tiling.data_ptr_;
62	  }
63	  tiling.inited_data_ptr = true;
64	  tiling.data_ptr_ = (uint8_t *)dataPtr;
65	  for (auto &ptr : tiling.saveBufferPtr) {
66	    TilingDef *sub_ptr = (TilingDef *)ptr.first;
67	    size_t offset = ptr.second;
68	    uint8_t *struct_ptr = tiling.data_ptr_ + offset;
69	    sub_ptr->SetDataPtr(struct_ptr);
70	  }
71	}
72	
73	void TilingDefImpl::SaveToBuffer(TilingDef &tiling, void *pdata, size_t capacity) {
74	  if (tiling.inited_data_ptr) {
75	#ifndef ASCENDC_DEVICE_REG_STATIC
76	    GELOGD("TilingDef::SaveToBuffer, op %s, data had been saved.", tiling.class_name_);
77	#endif
78	    return;
79	  }
80	  // copy tilingdata to buffer without struct tiling data.
81	  auto mem_ret = memcpy_s(pdata, capacity, tiling.data_ptr_, tiling.data_size_);
82	  if (mem_ret != EOK) {
83	#ifndef ASCENDC_DEVICE_REG_STATIC
84	    GELOGE(ge::GRAPH_FAILED,
85	           "TilingDef::SaveToBuffer failed: memcpy_s return op [%s] [%d], capacity = [%zu], data_size_ = [%zu].",
86	           tiling.class_name_, mem_ret, capacity, tiling.data_size_);
87	#endif
88	  }
89	}
90	
91	void TilingDefImpl::CheckAlignAndGenPlaceHolder(TilingDef &tiling, const char *name, size_t typeSize) {
92	  if (tiling.data_size_ % typeSize == 0) {
93	    return;
94	  }
95	  size_t alignSize = typeSize - (tiling.data_size_ % typeSize);
96	  tiling.field_info_.emplace_back(FieldInfo("uint8_t", name, alignSize));
97	  tiling.data_size_ += alignSize;
98	  return;
99	}
100	
101	void TilingDefImpl::InitData(TilingDef &tiling) {
102	#ifndef ASCENDC_DEVICE_REG_STATIC
103	  GELOGD("TilingDef::InitData, op %s, data size %d.", tiling.class_name_, tiling.data_size_);
104	#endif
105	  tiling.data_ptr_ = new (std::nothrow) uint8_t[tiling.data_size_]();
106	  if (tiling.data_ptr_ == nullptr) {
